    min_r, max_r = min(p[0] for p in pattern_coords), max(p[0] for p in pattern_coords)
    min_c, max_c = min(p[1] for p in pattern_coords), max(p[1] for p in pattern_coords)

    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

